// How far the paths' ink reaches from the corner placeMark puts at (left, top),
// in the symbol's units: 176.26 right (a little past the 176 of the logo box)
// and 104.12 down.
const MARK_INK_RIGHT = 176.26
const MARK_INK_BOTTOM = 104.12

function triangleWave(value) {
  const phase = value - Math.floor(value)
  return phase < 0.5 ? phase * 2 : 2 - phase * 2
}

const PALETTE = {
  cyan: '#55dfff',
  magenta: '#ff72c8',
  lime: '#b9ed67',
  amber: '#ffc56b',
  white: '#ffffff',
}
const AUTO_COLORS = [PALETTE.cyan, PALETTE.magenta, PALETTE.lime, PALETTE.amber, PALETTE.white]

const DEFAULT_SPEED = 0.18

// The speed field, in screen widths per half second (the logo moves twice its
// value in screen widths a second). 0 holds the logo still. A float field
// reaches the app as a number, and the runtime hands an empty or unreadable one
// over as 0, so a 0 counts only when the scene's own `speed` state is a number.
function readSpeed(app) {
  const speed = Number(app.config.speed)
  if (!Number.isFinite(speed)) {
    return DEFAULT_SPEED
  }
  if (speed !== 0) {
    return Math.max(0.02, speed)
  }
  return isNumber(app.state && app.state.speed) ? 0 : DEFAULT_SPEED
}

function isNumber(value) {
  if (typeof value === 'number') {
    return Number.isFinite(value)
  }
  return typeof value === 'string' && value.trim() !== '' && Number.isFinite(Number(value))
}

function colorFor(mode, bounceCount) {
  if (mode && mode !== 'auto') {
    return PALETTE[mode] || PALETTE.white
  }
  return AUTO_COLORS[bounceCount % AUTO_COLORS.length]
}

// The mark's transform: the symbol's top left corner (8, 44 in its own units)
// at left, top, drawn at scale.
function placeMark(left, top, scale) {
  return `translate(${(left - 8 * scale).toFixed(2)} ${(top - 44 * scale).toFixed(2)}) scale(${scale.toFixed(5)})`
}

// The mark only changes with its fill, so memo() hands back the element it
// made last frame (the shadow always, the logo until its next bounce).
const DvdMark = memo(({ fill }) => (
  <g fill={fill} fillRule="evenodd">
    <path d={DVD_LETTERS} />
    <path d={DVD_DISC} />
    <path d={DVD_VIDEO} />
  </g>
))

export function get(app, context) {
  const W = context?.imageWidth ?? app.frame.width
  const H = context?.imageHeight ?? app.frame.height
  const unit = Math.min(W, H)
  const logoW = W * 0.2
  const logoH = logoW * 0.62
  const speed = readSpeed(app)
  const horizontalTravel = Math.max(1, W - logoW)
  const verticalTravel = Math.max(1, H - logoH)
  const scale = logoW / 176
  const markHeight = 104 * scale
  const offsetY = (logoH - markHeight) / 2
  const shadow = Math.max(2, unit * 0.009)

  // Speed 0: a still logo in the middle of the panel.
  let x = horizontalTravel / 2
  let y = verticalTravel / 2
  let bounces = 0
  if (speed > 0) {
    const seconds = Date.now() / 1000
    const xCycles = (seconds * speed * W) / horizontalTravel
    const yCycles = (seconds * speed * W * 0.73) / verticalTravel
    // The shadow sits `shadow` px right of and below the logo, so the logo turns
    // where the shadow's ink meets the right or bottom edge. It waits there for
    // the moment the wave spends past that point, and moves as before elsewhere.
    const rightTurn = Math.max(0, Math.min(horizontalTravel, W - MARK_INK_RIGHT * scale - shadow))
    const bottomTurn = Math.max(0, Math.min(verticalTravel, H - offsetY - MARK_INK_BOTTOM * scale - shadow))
    x = Math.min(triangleWave(xCycles) * horizontalTravel, rightTurn)
    y = Math.min(triangleWave(yCycles) * verticalTravel, bottomTurn)
    bounces = Math.floor(xCycles * 2) + Math.floor(yCycles * 2)
  }
  const color = colorFor(app.config.logoColor, bounces)

  return (
    <svg width={W} height={H} viewBox={`0 0 ${W} ${H}`}>
      <rect x={0} y={0} width={W} height={H} fill="#090b14" />
      <g transform={placeMark(x + shadow, y + offsetY + shadow, scale)} opacity="0.32">
        <DvdMark fill="#000000" />
      </g>
      <g transform={placeMark(x, y + offsetY, scale)}>
        <DvdMark fill={color} />
      </g>
    </svg>
  )
}
